  var s = String(result);
  var key = 'data-mid=';
  var i = s.indexOf(key);
  var mid = '';
  if(i >= 0){
    var start = i + key.length;
    var qc = s.charCodeAt(start);
    var hasQ = (qc === 34);
    if(!hasQ){ hasQ = (qc === 39); }
    if(hasQ){ start = start + 1; }
    var end = start;
    while(end < s.length){
      var c = s.charCodeAt(end);
      if(hasQ){
        if(c === qc){ break; }
      } else {
        if(c === 32 || c === 62){ break; }
      }
      end = end + 1;
    }
    mid = s.substring(start, end);
  }
  if(!mid){
    var p = String(baseUrl).split('/works/');
