(function(){
  try{
    var hid = String(baseUrl).split('?')[0];
    hid = hid.substring(hid.lastIndexOf('/')+1);
    var dash = hid.indexOf('-');
    if(dash<0){ throw 'bad chapter url'; }
    var seg1 = hid.substring(0,dash), seg2 = hid.substring(dash+1);
    var b64 = seg1.replace(/-/g,'+').replace(/_/g,'/');
    while(b64.length%4!==0){ b64+='='; }
    var info = String(java.base64Decode(b64));
    var m = info.match(/-c:(\d+)/);
    if(!m){ throw 'bad hid:'+info; }
    var apiHid = String(java.base64Encode('c:'+m[1])).replace(/=+$/,'')+'-'+seg2;
    var body = String(java.ajax('https://hipapi1.s3file.top/v2/chapter?hid='+java.encodeURI(apiHid)));
    var j = JSON.parse(body);
    if(!j){ throw 'api:empty'; }
    if(j.code!==200){ throw 'api:'+j.message; }
    if(!j.data){ throw 'api:nodata'; }
    var d = j.data;
    var imgs;
    if(typeof d.images === 'string'){
      var payload = String(d.images);
      if(payload.indexOf('qM9')!==0){ throw 'bad prefix'; }
      if(payload.substring(payload.length-2)!=='Z7'){ throw 'bad suffix'; }
      var core = payload.substring(3, payload.length-2);
      var rem = core.length - 5;
      if(rem<0){ throw 'too short'; }
      var r = Math.floor(rem/3);
      var cd = Math.floor((rem-r)/2);
      var t = (rem-r)-cd;
      if(core.substring(cd, cd+2)!=='Vx'){ throw 'k1'; }
      if(core.substring(cd+2+t, cd+5+t)!=='pL0'){ throw 'k2'; }
      var fin = core.substring(cd+5+t) + core.substring(0, cd) + core.substring(cd+2, cd+2+t);
      var out1 = '';
      for(var i1=0, ci=0; i1<fin.length; i1+=7, ci++){
        var ch = fin.substring(i1, i1+7);
        if(ci%2===1){
          for(var k=ch.length-1; k>=0; k--){ out1 += ch.charAt(k); }
        } else {
          out1 += ch;
        }
      }
      var ASRC = '_-9876543210abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
      var ADST = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
      var b64out = '';
      for(var i2=0; i2<out1.length; i2++){
        var idx2 = ASRC.indexOf(out1.charAt(i2));
        if(idx2<0){ throw 'x0'; }
        b64out += ADST.charAt(idx2);
      }
      var std = b64out.replace(/-/g,'+').replace(/_/g,'/');
      while(std.length%4!==0){ std+='='; }
      var json = String(java.base64Decode(std));
      imgs = JSON.parse(json);
    } else {
      imgs = d.images;
    }
    if(!imgs){ imgs = []; }
    if(imgs.length<1){ throw 'empty images'; }
    var D = 2654435761, R = 2246822539;
    function q(t){ var l=Number(t); if(!isFinite(l)){ return null; } if(l<0){ return null; } if(l>4294967295){ return null; } return Math.floor(l)>>>0; }
    function deDecoy(a, l, u){
      var len=a.length, mm=q(l), g=q(u);
      if(mm===null){ return a; }
      if(g===null){ return a; }
      var b;
      if(typeof BigInt==='function'){
        b = Number((BigInt(g)*BigInt(D) ^ BigInt(len)*BigInt(R)) % BigInt(len));
      } else {
        var S=4294967296;
        var L=g*D, V=len*R;
        var Lh=Math.floor(L/S), Ll=L-Lh*S, Vh=Math.floor(V/S), Vl=V-Vh*S;
        b = ((Lh^Vh)>>>0)*S + ((Ll^Vl)>>>0);
        b = b % len;
      }
      if(b<0){ b=b+len; }
      var h = (mm^b)>>>0;
      if(h<len){ a.splice(h,1); }
      return a;
    }
    deDecoy(imgs, d.order_id, d.sid);
    var base = 'https://hip-tx-1.s3imgs.top';
    if(Number(d.line)===9){ base = 'https://hip-tx-s1.s3imgs.top'; }
    var out=[];
    for(var i3=0; i3<imgs.length; i3++){
      var p=String(imgs[i3]).replace(/^\s+|\s+$/g,'');
      if(p.length<1){ continue; }
      if(p.indexOf('//')===0){ p='https:'+p; }
      else if(p.indexOf('http')!==0){
        if(p.charAt(0)==='/'){ p=base+p; }
        else { p=base+'/'+p; }
      }
      out.push('<img src="'+p+'" />');
    }
    if(out.length<1){ throw 'no images'; }
    return out.join('\n');
  }catch(e){
    return '加载失败:'+e;
  }
})()
}}

